class Solution {
    int N;
    vector<int> sum;

    void update(int node, int l, int r, int p, int v) {
        if (l == r) { sum[node] += v; return; }
        int m = (l + r) / 2;
        if (p <= m) update(2*node, l, m, p, v);
        else update(2*node+1, m+1, r, p, v);
        sum[node] = sum[2*node] + sum[2*node+1];
    }

    int query(int node, int l, int r, int ql, int qr) {
        if (qr < l || r < ql) return 0;
        if (ql <= l && r <= qr) return sum[node];
        int m = (l + r) / 2;
        return query(2*node, l, m, ql, qr) + query(2*node+1, m+1, r, ql, qr);
    }

    // rightmost index in [ql,qr] with sum 0 (unused slot), or -1
    int findRight(int node, int l, int r, int ql, int qr) {
        if (qr < l || r < ql || sum[node] == r - l + 1) return -1;
        if (l == r) return l;
        int m = (l + r) / 2;
        int res = findRight(2*node+1, m+1, r, ql, qr);
        if (res != -1) return res;
        return findRight(2*node, l, m, ql, qr);
    }

public:
    int findMinimumTime(vector<vector<int>>& tasks) {
        N = 2048;
        sum.assign(2*N, 0);
        sort(tasks.begin(), tasks.end(), [](const vector<int>& a, const vector<int>& b) {
            return a[1] < b[1];
        });
        for (auto& t : tasks) {
            int s = t[0] - 1, e = t[1] - 1, d = t[2];
            int used = query(1, 0, N-1, s, e);
            int need = d - used;
            for (int k = 0; k < need; ++k) {
                int p = findRight(1, 0, N-1, s, e);
                update(1, 0, N-1, p, 1);
            }
        }
        return query(1, 0, N-1, 0, N-1);
    }
};
